import{_ as s,a0 as p,w as u,s as a,ao as l,I as i,x as t,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"使用 Linux 上的開源財務工具 Skrooge 管理你的預算 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 上的開源財務工具 Skrooge 管理你的預算 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 上的開源財務工具 Skrooge 管理你的預算 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 上的開源財務工具 Skrooge 管理你的預算 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20210210 Manage your budget on Linux with this open source finance tool","title":"使用 Linux 上的開源財務工具 Skrooge 管理你的預算","tag":"202206","desc":""},"relativePath":"202206/20210210 Manage your budget on Linux with this open source finance tool.md","filePath":"[post].md"}'),f={name:"202206/20210210 Manage your budget on Linux with this open source finance tool.md"};function d(g,o,m,x,k,L){const e=p("Link");return u(),a("div",null,[o[31]||(o[31]=l('<h1 id="使用-linux-上的開源財務工具-skrooge-管理你的預算" tabindex="-1">使用 Linux 上的開源財務工具 Skrooge 管理你的預算 <a class="header-anchor" href="#使用-linux-上的開源財務工具-skrooge-管理你的預算" aria-label="Permalink to “使用 Linux 上的開源財務工具 Skrooge 管理你的預算”">​</a></h1><blockquote><p>使用開源預算工具 Skrooge 讓你的財務管理更加輕鬆。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202206/06/115449f0uy9guxxokj0umo.jpg" alt=""></p><p>2021 年，人們喜歡 Linux 的理由比以往任何時候都多。在本系列中，我將分享使用 Linux 的 21 個不同理由。本篇介紹的是個人財務管理。</p><p>個人財務可能很難管理。當你沒有足夠的錢在沒有經濟援助的情況下度日時，這可能是令人沮喪甚至不安的，而當你確實有所需的錢卻又不清楚每個月的去向時，這可能會令人驚訝地難以接受。更糟糕的是，我們經常被告知要“制定預算”，好像宣佈你每個月的花銷就能在某種程度上體現出你需要多少錢。底線是：制定預算是困難的，沒有達到你的財務目標是令人沮喪的。但這仍然很重要，Linux 有幾個工具可以幫助使任務變得可管理。</p><h3 id="理財" tabindex="-1">理財 <a class="header-anchor" href="#理財" aria-label="Permalink to “理財”">​</a></h3><p>就像生活中的其他事情一樣，我們都有自己的方法來跟蹤我們的財務。我過去常常採取一種簡單而直接的方法：我的薪水支票被存入一個賬户，然後我會提取一定比例的現金。一旦我錢包裏的錢沒了，我就得等到下一個發薪日才能花錢。我用了一天沒有午餐的時間，就明白了我必須認真對待我的目標，並相應地調整了我的消費行為。對於當時我的簡單的生活方式來説，這是一種讓我對自己的收入保持誠實的有效手段，但它並不能很好地轉化為在線商業交易、長期公用事業合同、投資等等。</p><p>隨着我不斷完善我的財務跟蹤方式，我瞭解到個人會計始終是一個不斷發展的過程。我們每個人都有獨特的財務狀況，這告訴我們可以或應該使用什麼樣的解決方案來跟蹤我們的收入和債務。如果你失業了，那麼你的預算目標可能是儘可能少花錢。如果你在工作，但在還學生貸款，那麼你的目標可能是向銀行匯款。如果你在工作，但計劃退休，那麼你可能會盡可能多地存錢。</p><p>關於預算，要記住的一點是，它是為了將你的財務現實與你的財務 <em>目標</em> 進行比較。你無法避免一些開支，但在這些之後，你可以設定自己的優先事項。如果你沒有達到你的目標，你可以調整自己的行為或改寫你的目標，使其更好地反映現實。調整你的財務計劃並不意味着你失敗了，這只是意味着你最初的預測並不準確。在困難時期，你可能無法達到任何預算目標，但如果你堅持你的預算，你會學到很多關於維持你目前的生活方式（無論它是什麼）所需要的財務手段。隨着時間的推移，你可以學習調整你可能從未意識到的變化。例如，由於遠程工作已成為一種被廣泛接受的選擇，人們正在搬到農村城鎮以降低生活成本。看到這樣一種生活方式的轉變可以改變你的預算報告，真是令人震驚。</p>',9)),i("p",null,[o[1]||(o[1]=t("重點是，預算編制是一項經常被低估的活動，這在很大程度上是因為它令人生畏。重要的是要認識到，無論你的專業水平或對財務的興趣如何，你都可以進行預算。無論你 ",-1)),n(e,{href:"https://opensource.com/article/20/3/libreoffice-templates"},{default:r(()=>[...o[0]||(o[0]=[t("只使用 LibreOffice 電子表格",-1)])]),_:1}),o[2]||(o[2]=t("，還是嘗試專用的財務應用程序，你都可以設定目標，跟蹤自己的行為，並學到許多寶貴的經驗教訓，這些經驗教訓最終可能會帶來回報。",-1))]),o[32]||(o[32]=i("h3",{id:"開源會計",tabindex:"-1"},[t("開源會計 "),i("a",{class:"header-anchor",href:"#開源會計","aria-label":"Permalink to “開源會計”"},"​")],-1)),i("p",null,[o[9]||(o[9]=t("有幾個專用於 ",-1)),n(e,{href:"https://opensource.com/life/17/10/personal-finance-tools-linux"},{default:r(()=>[...o[3]||(o[3]=[t("Linux 的個人理財應用程序",-1)])]),_:1}),o[10]||(o[10]=t("，包括 ",-1)),n(e,{href:"http://homebank.free.fr/en/index.php"},{default:r(()=>[...o[4]||(o[4]=[t("HomeBank",-1)])]),_:1}),o[11]||(o[11]=t("、",-1)),n(e,{href:"https://www.moneymanagerex.org/download"},{default:r(()=>[...o[5]||(o[5]=[t("Money Manager EX",-1)])]),_:1}),o[12]||(o[12]=t("、",-1)),n(e,{href:"https://opensource.com/article/20/2/gnucash"},{default:r(()=>[...o[6]||(o[6]=[t("GNUCash",-1)])]),_:1}),o[13]||(o[13]=t("、",-1)),n(e,{href:"https://kmymoney.org/download.html"},{default:r(()=>[...o[7]||(o[7]=[t("KMyMoney",-1)])]),_:1}),o[14]||(o[14]=t(" 和 ",-1)),n(e,{href:"https://apps.kde.org/en/skrooge"},{default:r(()=>[...o[8]||(o[8]=[t("Skrooge",-1)])]),_:1}),o[15]||(o[15]=t("。所有這些應用程序本質上都是賬本，你可以在每個月底（或每當你查看帳户時）退回到一個地方，從你的銀行導入數據，並審查你的支出如何與你為自己設定的預算保持一致。",-1))]),o[33]||(o[33]=l('<p><img src="https://opensource.com/sites/default/files/skrooge.jpg" alt="顯示財務數據的 Skrooge 界面"></p><p>我使用 Skrooge 作為我的個人預算跟蹤器。即便面對多個銀行賬户，它也能輕鬆自如的設置。與大多數開源金融應用程序一樣，Skrooge 可以導入多種文件格式，因此我的工作流程大致如下：</p><ol><li>登錄我的銀行。</li><li>將當月的銀行對賬單導出為 QIF 文件。</li><li>打開 Skrooge。</li><li>導入 QIF 文件。每個文件都會自動分配到相應的帳户。</li><li>對照我為自己設定的預算目標審查我的支出。如果我超支了，那麼我就會扣減下個月的目標（這樣我就會理性地少花錢來彌補差額）。如果我尚未超出我的目標預算，那麼我會把多餘的部分移到 12 月的預算中（這樣我在年底就會有更多的支出份額）。</li></ol><p>我只跟蹤了 Skrooge 中的家庭預算的一部分。Skrooge 通過一個動態資料庫簡化了這一過程，該資料庫允許我使用自定義標籤一次對多個交易進行分類。這使我可以輕鬆地從一般家庭和公用事業支出中提取我的個人支出，並且我可以在查看 Skrooge 提供的自動生成的報告時利用這些類別。</p><p><img src="https://opensource.com/sites/default/files/skrooge-pie_0.jpg" alt="Skrooge 預算餅圖"></p><p>最重要的是，流行的 Linux 財務應用程序使我能夠以最適合我的方式管理我的預算。例如，我的合作伙伴更喜歡使用 LibreOffice 電子表格，但我只需要付出很少的努力就可以從家庭預算中提取 CSV 文件，將其導入到 Skrooge，並使用一組更新的數據集。不存在供應商鎖定和不兼容。該系統靈活敏捷，使我們能夠在更多地瞭解有效預算和生活中的情況時調整我們的預算和跟蹤支出的方法。</p><h3 id="開放選擇" tabindex="-1">開放選擇 <a class="header-anchor" href="#開放選擇" aria-label="Permalink to “開放選擇”">​</a></h3><p>世界各地的貨幣市場各不相同，我們每個人與之互動的方式也決定了我們可以使用哪些工具。歸根結底，你對財務類軟件的選擇必須基於自己的需求。開源做得特別好的一件事是為用户提供了選擇的自由。</p><p>在設定自己的財務目標時，我很欣賞我可以使用最適合我個人計算風格的任何應用程序。我可以控制我在生活中如何處理數據，即使是我不一定喜歡處理的數據。Linux 及其令人驚歎的應用程序集使它不再是一件苦差事。</p><p>在 Linux 上嘗試一些財務應用程序，看看你是否可以激勵自己設定一些目標並節省開支吧！</p><hr>',11)),i("p",null,[o[17]||(o[17]=t("via: ",-1)),n(e,{href:"https://opensource.com/article/21/2/linux-skrooge"},{default:r(()=>[...o[16]||(o[16]=[t("https://opensource.com/article/21/2/linux-skrooge",-1)])]),_:1})]),i("p",null,[o[22]||(o[22]=t("作者：",-1)),n(e,{href:"https://opensource.com/users/seth"},{default:r(()=>[...o[18]||(o[18]=[t("Seth Kenlon",-1)])]),_:1}),o[23]||(o[23]=t(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:r(()=>[...o[19]||(o[19]=[t("lujun9972",-1)])]),_:1}),o[24]||(o[24]=t(" 譯者：",-1)),n(e,{href:"https://github.com/hanszhao80"},{default:r(()=>[...o[20]||(o[20]=[t("hanszhao80",-1)])]),_:1}),o[25]||(o[25]=t(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:r(()=>[...o[21]||(o[21]=[t("wxy",-1)])]),_:1})]),i("p",null,[o[28]||(o[28]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[26]||(o[26]=[t("LCTT",-1)])]),_:1}),o[29]||(o[29]=t(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:r(()=>[...o[27]||(o[27]=[t("Linux中國",-1)])]),_:1}),o[30]||(o[30]=t(" 榮譽推出",-1))])])}const C=s(f,[["render",d]]);export{b as __pageData,C as default};
